/** Gambar wajah siswa (tanpa lingkaran latar). jenis 'L' / 'P', i = 0–5. */
export function WajahSiswa({ jenis = 'P', i = 0, className = '' }) {
  const daftar = String(jenis).toUpperCase().startsWith('P') ? SISWA_P : SISWA_L
  return <svg className={className} viewBox="0 0 100 100" aria-hidden="true">{daftar[((i % 6) + 6) % 6]}</svg>
}

/** Gambar wajah staf, i = 0–11. */
export function WajahStaf({ i = 0, className = '' }) {
  return <svg className={className} viewBox="0 0 100 100" aria-hidden="true">{STAF[((i % 12) + 12) % 12]}</svg>
}

