/** Nama gambar untuk satu emoji kegiatan ('' kalau belum ada gambarnya). */
export const namaGambarKegiatan = (emoji = '') => EMOJI_KE_GAMBAR[String(emoji).replace(/\uFE0F/g, '')] || ''

/**
 * Ikon bergambar untuk jenis biaya kegiatan. Datanya tetap menyimpan emoji
 * (biaya.emoji) supaya database tidak berubah — di layar, emoji itu diganti
 * gambar. Emoji yang belum punya gambar tetap tampil sebagai emoji.
 *   latar=true → ubin pastel membulat di belakang gambar
 */
export function GambarKegiatan({ emoji, size = 40, latar = true, className = '' }) {
  const nama = namaGambarKegiatan(emoji)
  const bg = latar ? (LATAR_KEGIATAN[nama] || '#F1F4F9') : 'transparent'
  return (
    <span
      aria-hidden="true"
      className={`grid shrink-0 place-items-center ${latar ? 'rounded-[30%]' : ''} ${className}`}
      style={{ width: size, height: size, background: bg }}
    >
      {nama ? (
        <svg viewBox="0 0 48 48" style={{ width: latar ? '76%' : '100%', height: latar ? '76%' : '100%' }}>{KEGIATAN[nama]}</svg>
      ) : (
        <span style={{ ...FONT_EMOJI, fontSize: Math.round(size * 0.55) }}>{emoji}</span>
      )}
    </span>
  )
}
